<?php require 'config.php';require 'auth.php';requireLogin();$id=(int)($_GET['id']??0);$c=read_data('categories');$idx=find_index($c,$id);if($idx!==null){array_splice($c,$idx,1);write_data('categories',$c);$items=read_data('items');foreach($items as &$i)if((int)$i['category_id']===$id)$i['category_id']=null;unset($i);write_data('items',$items);}$_SESSION['flash']=['type'=>'success','message'=>'Kategori berhasil dihapus.'];redirect('categories.php');